// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import { Grommet, Box, NameValueList, NameValuePair, Select, Text } from 'grommet';

const App = () => (
  <Grommet>
    <Box pad="large" background="light-1">
      {/* valueProps.align='start' yields misalignment between name and control */}
      <NameValueList valueProps={{ width: 'auto', align: 'start' }}>
        <NameValuePair name={<Text>File log level</Text>}>
          <Select
            options={[
              'Debug',
              'Info',
              'Warning',
              'Error',
              'Panic',
              'Fatal',
            ]}
            placeholder="Select level"
          />
        </NameValuePair>
      </NameValueList>
    </Box>
  </Grommet>
);

ReactDOM.render(<App />, document.getElementById('root'));
